import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"プレビューと動作確認","description":"","frontmatter":{},"headers":[],"relativePath":"guides/testing.md","filePath":"guides/testing.md","lastUpdated":1793464466000}`),a={name:`guides/testing.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="プレビューと動作確認" tabindex="-1">プレビューと動作確認 <a class="header-anchor" href="#プレビューと動作確認" aria-label="Permalink to “プレビューと動作確認”">​</a></h1><h2 id="_3つの確認方法" tabindex="-1">3つの確認方法 <a class="header-anchor" href="#_3つの確認方法" aria-label="Permalink to “3つの確認方法”">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>目的</th></tr></thead><tbody><tr><td>管理画面内の表示イメージ</td><td>入力中の見た目を確認する</td></tr><tr><td>施策一覧のプレビュー</td><td>実ページへ1回だけ強制表示する</td></tr><tr><td>動作確認の診断パネル</td><td>通常の計測・送信・判断を観測する</td></tr></tbody></table><p>システムの更新用Cloudflare Previewは、<a href="./../getting-started/preview-production">別の環境を確認する機能</a>です。</p><h2 id="実ページへ確認表示する" tabindex="-1">実ページへ確認表示する <a class="header-anchor" href="#実ページへ確認表示する" aria-label="Permalink to “実ページへ確認表示する”">​</a></h2><ol><li>内容を下書き保存する。</li><li>施策一覧の「プレビュー」を押す。</li><li>確認したいページURLを入力する。</li><li>「ページを開いて確認」を押し、管理画面も開いたままにする。</li></ol><p>保存済み下書きを優先し、なければ保存済みの配信内容を使います。未保存の編集は含みません。停止中や通常配信前の施策も確認できます。</p><h2 id="urlの条件" tabindex="-1">URLの条件 <a class="header-anchor" href="#urlの条件" aria-label="Permalink to “URLの条件”">​</a></h2><p>サイトの登録Origin、収集許可/除外経路、施策の表示対象に一致する必要があります。たとえば完全一致<code>/ja/</code>の施策を、<code>/ja/products/a</code>で確認することはできません。</p><p>対象ページには最新版のSDKが必要です。CMPによりSDK自体が読み込まれない場合は起動できません。サイトのHTMLを勝手に書き換えたり、タグを自動注入する仕組みではありません。</p><h2 id="_1回限りの仕組み" tabindex="-1">1回限りの仕組み <a class="header-anchor" href="#_1回限りの仕組み" aria-label="Permalink to “1回限りの仕組み”">​</a></h2><p>確認チケットは5分・1回限りです。管理画面から今回開いたタブへ渡し、指定施策を表示します。チケットそのものをページURLやWeb Storageへ保存しません。</p><p>確認中は通常の計測・自動判断を休止します。Jevを呼ばず、通常の履歴、表示回数、閉じた状態を更新しません。ページ上にも確認表示であることを示します。</p><p>閉じる・ページ移動で終了します。同じURLのコピーや再読み込みで強制表示は引き継ぎません。再読み込み後に条件を満たして通常配信される場合は、別の動作です。</p><h2 id="表示できなかった場合" tabindex="-1">表示できなかった場合 <a class="header-anchor" href="#表示できなかった場合" aria-label="Permalink to “表示できなかった場合”">​</a></h2><p>期限切れ、設定変更、権限変更、CSP、画像、ポップアップ制限、COOP等を確認します。チケットの引換後に描画失敗しても使用済みになるため、新しいプレビューを起動してください。</p><p>独自JavaScriptの確認は管理者以上に限ります。作者はpreview modeで独自の計測や更新を抑止してください。</p><h2 id="配信の最終確認" tabindex="-1">配信の最終確認 <a class="header-anchor" href="#配信の最終確認" aria-label="Permalink to “配信の最終確認”">​</a></h2><p>強制表示が成功しても、対象者判定が正しいと検証したことにはなりません。通常配信では、同意・有効閲覧・確定条件・Jevの判定値・閾値・表示制約を通ります。<a href="./debugging">診断パネル</a>で通常の流れも確認します。</p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};